#!/usr/bin/env python3
"""Apply the Zero G MX2001 + ETo reference recession to every modeled canyon."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TRACKER = ROOT / "tracker.py"
APP = ROOT / "docs" / "app.js"
README = ROOT / "README.md"
TEST = ROOT / "tests" / "test_tracker.py"
EVENT_TEST = ROOT / "tests" / "test_event_accumulation.py"
FRONTEND_TEST = ROOT / "tests" / "test_frontend_contract.py"


def replace_if_present(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        return text
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one old match, found {count}")
    return text.replace(old, new, 1)


tracker = TRACKER.read_text(encoding="utf-8")

old_metadata = '''            "cumulative_refill_explanation": (\n                "Current conditions lose modeled storage between storms. Zero G now uses an "\n                "MX2001 field-calibrated seasonal loss model: 1.28 inches/day of empirical "\n                "Navajo sandstone/seepage-equivalent recession plus monthly Moab reference "\n                "ETo. Other canyons retain the provisional fixed percentage-point decay until "\n                "their own geology or field data support a canyon-specific loss model. New "\n                "modeled runoff is added to the decayed balance and capped at 100%."\n            ),\n            "pool_loss_explanation": (\n                "Zero G's central loss calibration uses the stable lower MX2001 logger from "\n                "August 1 through September 7, 2026. The upper logger is excluded from the "\n                "central rate because it physically relocated on August 8 and remained a "\n                "shallower, more exposed high-loss comparison. The 1.28 in/day residual is an "\n                "empirical stage-equivalent term after subtracting USU Moab monthly reference "\n                "ETo; it includes Navajo sandstone/fracture seepage and any inseparable quiet-"\n                "pool drainage. The percent conversion uses the lower logger's initial 11.9288-"\n                "ft water column and is therefore a field-calibrated stage-equivalent condition "\n                "model, not a surveyed stage-volume curve."\n            ),'''
new_metadata = '''            "cumulative_refill_explanation": (\n                "All canyon condition balances and cumulative refill balances use the same "\n                "transferred Zero G reference recession between storms and from the most recent "\n                "storm through the present. The reference combines 1.28 inches/day of empirical "\n                "Navajo sandstone/seepage-equivalent loss with monthly Moab reference ETo. "\n                "New modeled runoff is added after time-integrated loss and storage is capped "\n                "at 100%."\n            ),\n            "pool_loss_explanation": (\n                "The loss reference comes from the stable lower HOBO MX2001 logger in Zero G, "\n                "deployed August 1 through September 7, 2026. The upper logger is excluded from "\n                "the central rate because it physically relocated on August 8 and remained a "\n                "shallower, more exposed high-loss comparison. After subtracting USU Moab "\n                "monthly reference ETo normals (2000-2022), the stable lower logger supports a "\n                "1.28 in/day empirical Navajo/seepage-equivalent residual. The percentage "\n                "conversion uses the lower logger's initial 11.9288-ft water column. That same "\n                "seasonal stage-equivalent percentage-point loss is transferred to all 22 "\n                "modeled canyons until canyon-specific recession data are available. This is an "\n                "explicit transfer assumption, not a claim that every canyon has identical pool "\n                "geometry, evaporation, fractures, or seepage."\n            ),'''
tracker = replace_if_present(tracker, old_metadata, new_metadata, "method metadata")

old_decay = '''    default_decay_points_per_day = max(\n        0.0, float(config.get("condition_decay_percentage_points_per_day", 0.8))\n    )\n    if canyon.canyon_id == "zerog":\n        current_loss_components = zero_g_loss_components(now)\n        decay_points_per_day = float(\n            current_loss_components["percentage_points_per_day"]\n        )\n    else:\n        current_loss_components = None\n        decay_points_per_day = default_decay_points_per_day\n\n    def apply_decay(value: float, start: datetime, end: datetime) -> float:\n        if canyon.canyon_id == "zerog":\n            loss_ratio = zero_g_integrated_loss_ratio(start, end)\n        else:\n            elapsed_days = max(0.0, (end - start).total_seconds() / 86400.0)\n            loss_ratio = default_decay_points_per_day / 100.0 * elapsed_days\n        return max(0.0, value - loss_ratio)\n'''
new_decay = '''    current_loss_components = zero_g_loss_components(now)\n    decay_points_per_day = float(\n        current_loss_components["percentage_points_per_day"]\n    )\n\n    def apply_decay(value: float, start: datetime, end: datetime) -> float:\n        loss_ratio = zero_g_integrated_loss_ratio(start, end)\n        return max(0.0, value - loss_ratio)\n'''
tracker = replace_if_present(tracker, old_decay, new_decay, "all-canyon condition decay")

old_condition = '''    if canyon.canyon_id == "zerog" and current_loss_components is not None:\n        loss_fields = {\n            "loss_model": "zero_g_mx2001_et_plus_navajo",\n            "decay_percentage_points_per_day": round(decay_points_per_day, 3),\n            "eto_inches_per_day": round(\n                float(current_loss_components["eto_inches_per_day"]), 3\n            ),\n            "navajo_seepage_inches_per_day": round(\n                float(current_loss_components["navajo_seepage_inches_per_day"]), 3\n            ),\n            "total_loss_inches_per_day": round(\n                float(current_loss_components["total_loss_inches_per_day"]), 3\n            ),\n            "reference_pool_depth_ft": ZERO_G_REFERENCE_LOWER_POOL_DEPTH_FT,\n            "retention_class": "Zero G stable-lower-MX2001 field calibration",\n            "loss_calibration_note": (\n                "Central rate uses the unmoved lower logger. Upper logger moved on "\n                "2026-08-08 and is retained only as an exposed/high-loss bound."\n            ),\n        }\n    else:\n        loss_fields = {\n            "loss_model": "provisional_linear_decay",\n            "decay_percentage_points_per_day": decay_points_per_day,\n            "retention_class": "provisional reference-canyon field calibration",\n        }\n'''
new_condition = '''    loss_fields = {\n        "loss_model": "zero_g_mx2001_et_plus_navajo",\n        "decay_percentage_points_per_day": round(decay_points_per_day, 3),\n        "eto_inches_per_day": round(\n            float(current_loss_components["eto_inches_per_day"]), 3\n        ),\n        "navajo_seepage_inches_per_day": round(\n            float(current_loss_components["navajo_seepage_inches_per_day"]), 3\n        ),\n        "total_loss_inches_per_day": round(\n            float(current_loss_components["total_loss_inches_per_day"]), 3\n        ),\n        "reference_pool_depth_ft": ZERO_G_REFERENCE_LOWER_POOL_DEPTH_FT,\n        "retention_class": "Transferred Zero G stable-lower-MX2001 reference calibration",\n        "loss_calibration_note": (\n            "Reference rate comes from the unmoved lower Zero G logger; the upper "\n            "logger moved on 2026-08-08 and is retained only as an exposed/high-loss "\n            "bound. This reference recession is transferred to all modeled canyons."\n        ),\n    }\n'''
tracker = replace_if_present(tracker, old_condition, new_condition, "all-canyon condition metadata")

old_cumulative = '''    for event in events:\n        runoff = float(\n            event.get("direct_runoff_ft3", event.get("estimated_runoff_ft3", 0.0))\n            or 0.0\n        )\n        before = balance\n        raw_after = before + max(0.0, runoff)\n        balance = min(target, raw_after)\n        overflow = max(0.0, raw_after - target)\n        overflow_total += overflow\n        ratio = balance / target if target > 0 else 0.0\n        timestamp = event.get("end_utc") or event.get("start_utc")\n\n        for percent in (25, 50, 75, 100):\n            key = str(percent)\n            if milestones[key] is None and ratio + 1e-9 >= percent / 100.0:\n                milestones[key] = timestamp\n\n        history.append(\n            {\n                "start_utc": event.get("start_utc"),\n                "end_utc": event.get("end_utc"),\n                "classification": event.get("classification"),\n                "classification_label": event.get("classification_label"),\n                "basin_rain_inches": event.get("basin_rain_inches"),\n                "direct_runoff_ft3": round(runoff),\n                "event_fill_ratio": event.get("fill_ratio"),\n                "balance_before_ft3": round(before),\n                "cumulative_balance_ft3": round(balance),\n                "cumulative_ratio": round(ratio, 2),\n                "cumulative_percent": min(100, round(ratio * 100)),\n                "overflow_ft3": round(overflow),\n            }\n        )\n\n    canyon_status["refill_history"] = [\n        item\n        for item in reversed(history)\n        if parse_utc(item.get("end_utc") or item["start_utc"]) >= detail_cutoff\n    ]\n    canyon_status["cumulative_refill_evidence"] = {\n        "event_count": len(history),\n        "period_start_utc": history[0]["start_utc"] if history else None,\n        "through_utc": history[-1]["end_utc"] if history else None,\n        "balance_ft3": round(balance),\n        "ratio": round(balance / target, 2) if target > 0 else 0.0,\n        "percent": min(100, round(balance / target * 100)) if target > 0 else 0,\n        "overflow_ft3": round(overflow_total),\n        "milestones_utc": milestones,\n        "loss_model": "not_modeled",\n        "assumption": (\n            "Starts at zero storage at the first retained modeled event and "\n            "subtracts no evaporation, seepage, drainage, or other losses."\n        ),\n    }\n'''
new_cumulative = '''    balance_time: datetime | None = None\n    cumulative_loss_total = 0.0\n    for event in events:\n        event_time = event_end_utc(event)\n        loss_before = 0.0\n        if balance_time is not None and balance > 0.0:\n            loss_ratio = zero_g_integrated_loss_ratio(balance_time, event_time)\n            loss_before = min(balance, target * loss_ratio)\n            balance = max(0.0, balance - loss_before)\n            cumulative_loss_total += loss_before\n\n        runoff = float(\n            event.get("direct_runoff_ft3", event.get("estimated_runoff_ft3", 0.0))\n            or 0.0\n        )\n        before = balance\n        raw_after = before + max(0.0, runoff)\n        balance = min(target, raw_after)\n        overflow = max(0.0, raw_after - target)\n        overflow_total += overflow\n        ratio = balance / target if target > 0 else 0.0\n        timestamp = event.get("end_utc") or event.get("start_utc")\n        balance_time = event_time\n\n        for percent in (25, 50, 75, 100):\n            key = str(percent)\n            if milestones[key] is None and ratio + 1e-9 >= percent / 100.0:\n                milestones[key] = timestamp\n\n        history.append(\n            {\n                "start_utc": event.get("start_utc"),\n                "end_utc": event.get("end_utc"),\n                "classification": event.get("classification"),\n                "classification_label": event.get("classification_label"),\n                "basin_rain_inches": event.get("basin_rain_inches"),\n                "direct_runoff_ft3": round(runoff),\n                "event_fill_ratio": event.get("fill_ratio"),\n                "modeled_loss_since_prior_event_ft3": round(loss_before),\n                "balance_before_ft3": round(before),\n                "cumulative_balance_ft3": round(balance),\n                "cumulative_ratio": round(ratio, 2),\n                "cumulative_percent": min(100, round(ratio * 100)),\n                "overflow_ft3": round(overflow),\n            }\n        )\n\n    loss_since_latest_event = 0.0\n    if balance_time is not None and balance > 0.0:\n        loss_ratio = zero_g_integrated_loss_ratio(balance_time, now)\n        loss_since_latest_event = min(balance, target * loss_ratio)\n        balance = max(0.0, balance - loss_since_latest_event)\n        cumulative_loss_total += loss_since_latest_event\n\n    current_cumulative_loss = zero_g_loss_components(now)\n    canyon_status["refill_history"] = [\n        item\n        for item in reversed(history)\n        if parse_utc(item.get("end_utc") or item["start_utc"]) >= detail_cutoff\n    ]\n    canyon_status["cumulative_refill_evidence"] = {\n        "event_count": len(history),\n        "period_start_utc": history[0]["start_utc"] if history else None,\n        "through_utc": utc_text(now) if history else None,\n        "balance_ft3": round(balance),\n        "ratio": round(balance / target, 2) if target > 0 else 0.0,\n        "percent": min(100, round(balance / target * 100)) if target > 0 else 0,\n        "overflow_ft3": round(overflow_total),\n        "modeled_loss_ft3": round(cumulative_loss_total),\n        "loss_since_latest_event_ft3": round(loss_since_latest_event),\n        "milestones_utc": milestones,\n        "loss_model": "zero_g_mx2001_et_plus_navajo",\n        "decay_percentage_points_per_day": round(\n            float(current_cumulative_loss["percentage_points_per_day"]), 3\n        ),\n        "eto_inches_per_day": round(\n            float(current_cumulative_loss["eto_inches_per_day"]), 3\n        ),\n        "navajo_seepage_inches_per_day": round(\n            float(current_cumulative_loss["navajo_seepage_inches_per_day"]), 3\n        ),\n        "total_loss_inches_per_day": round(\n            float(current_cumulative_loss["total_loss_inches_per_day"]), 3\n        ),\n        "reference_pool_depth_ft": ZERO_G_REFERENCE_LOWER_POOL_DEPTH_FT,\n        "assumption": (\n            "Starts at zero storage at the first retained modeled event, subtracts "\n            "the transferred Zero G stable-lower-MX2001 + seasonal Moab ETo loss "\n            "between storms and through the present, then adds modeled runoff and "\n            "caps storage at 100%."\n        ),\n    }\n'''
tracker = replace_if_present(tracker, old_cumulative, new_cumulative, "all-canyon cumulative loss")
TRACKER.write_text(tracker, encoding="utf-8")

app = APP.read_text(encoding="utf-8")
old_app = '''      ${condition.loss_model === "zero_g_mx2001_et_plus_navajo"\n        ? `Reference-canyon loss is field-calibrated from the stable lower MX2001 logger: ${number(condition.navajo_seepage_inches_per_day, 2)} in/day Navajo/seepage-equivalent loss + ${number(condition.eto_inches_per_day, 2)} in/day seasonal ETo = ${number(condition.total_loss_inches_per_day, 2)} in/day currently (${number(condition.decay_percentage_points_per_day, 2)} stage-equivalent percentage points/day).`\n        : `The provisional condition percentage decreases ${number(condition.decay_percentage_points_per_day || 0.8, 1)} point per day.`}\n'''
new_app = '''      ${condition.loss_model === "zero_g_mx2001_et_plus_navajo"\n        ? `All-canyon loss uses the transferred Zero G stable-lower-MX2001 reference: ${number(condition.navajo_seepage_inches_per_day, 2)} in/day empirical Navajo/seepage-equivalent loss + ${number(condition.eto_inches_per_day, 2)} in/day seasonal Moab ETo = ${number(condition.total_loss_inches_per_day, 2)} in/day currently (${number(condition.decay_percentage_points_per_day, 2)} stage-equivalent percentage points/day). The Zero G reference uses an 11.9288-ft lower-logger water column and is applied to every canyon until canyon-specific recession data exist.`\n        : `Pool-loss calibration unavailable.`}\n'''
app = replace_if_present(app, old_app, new_app, "frontend condition explanation")

old_methods = '''    <h3>Classification language</h3>\n'''
new_methods = '''    <h3>All-canyon pool-loss reference</h3>\n    <p><strong>What is used:</strong> the stable lower HOBO MX2001 recession measured in Zero G from Aug. 1-Sept. 7, 2026. The upper logger is not used in the central calibration because it physically relocated on Aug. 8.</p>\n    <p><strong>Operational equation:</strong> 1.28 in/day empirical Navajo/seepage-equivalent residual + Utah State University Moab monthly reference ETo normals (2000-2022). The conversion to condition loss uses the lower logger's initial 11.9288-ft water column. The resulting seasonal percentage-point loss is transferred to all 22 canyons, including cumulative balances between storms and loss after the latest storm.</p>\n    <p><strong>Interpretation:</strong> this is a reference-transfer assumption for operations, not evidence that every canyon has the same fractures, pool geometry, shade, evaporation, or seepage. Replace it canyon-by-canyon when better recession data become available.</p>\n\n    <h3>Classification language</h3>\n'''
app = replace_if_present(app, old_methods, new_methods, "frontend methods readme")
APP.write_text(app, encoding="utf-8")

readme = README.read_text(encoding="utf-8")
old_readme = '''New modeled runoff is added after the time-integrated loss and the condition balance is capped at 100%.\n'''
new_readme = '''New modeled runoff is added after the time-integrated loss and the condition balance is capped at 100%. The same loss integration is also used in the cumulative refill balance: loss is deducted between retained storms and again from the most recent storm through the current model time before the displayed balance is calculated. Individual historical storm runoff/fill ratios are preserved as the storm results that were modeled for those events; the transferred recession changes the evolving storage balance, not the stored storm evidence.\n'''
readme = replace_if_present(readme, old_readme, new_readme, "README all-canyon cumulative-loss disclosure")
README.write_text(readme, encoding="utf-8")

test = TEST.read_text(encoding="utf-8")
old_test = '''        self.assertIn("MX2001", method["cumulative_refill_explanation"])\n        self.assertIn("1.28 in/day", method["pool_loss_explanation"])\n        self.assertIn("August 8", method["pool_loss_explanation"])\n'''
new_test = '''        self.assertIn("All canyon", method["cumulative_refill_explanation"])\n        self.assertIn("cumulative refill balances", method["cumulative_refill_explanation"])\n        self.assertIn("1.28 in/day", method["pool_loss_explanation"])\n        self.assertIn("all 22 modeled canyons", method["pool_loss_explanation"])\n        self.assertIn("August 8", method["pool_loss_explanation"])\n'''
test = replace_if_present(test, old_test, new_test, "metadata tests")
TEST.write_text(test, encoding="utf-8")

event_test = EVENT_TEST.read_text(encoding="utf-8")
old_unknown = '''        self.assertIsNone(condition["percent"])\n        self.assertEqual(condition["current_condition"], "unknown")\n        self.assertEqual(condition["confidence"], "Unknown")\n'''
new_unknown = '''        self.assertIsNone(condition["percent"])\n        self.assertEqual(condition["current_condition"], "unknown")\n        self.assertEqual(condition["confidence"], "Unknown")\n        self.assertEqual(condition["loss_model"], "zero_g_mx2001_et_plus_navajo")\n        self.assertAlmostEqual(condition["navajo_seepage_inches_per_day"], 1.28, places=2)\n        self.assertAlmostEqual(condition["decay_percentage_points_per_day"], 1.07, delta=0.05)\n'''
event_test = replace_if_present(event_test, old_unknown, new_unknown, "non-Zero-G transfer test")
EVENT_TEST.write_text(event_test, encoding="utf-8")

frontend_test = FRONTEND_TEST.read_text(encoding="utf-8")
old_frontend_test = '''        self.assertIn("applied to every canyon", self.app)\n'''
new_frontend_test = '''        self.assertIn("applied to every canyon", self.app)\n        self.assertIn("All-canyon pool-loss reference", self.app)\n        self.assertIn("all 22 canyons", self.app)\n        self.assertIn("Utah State University Moab monthly reference ETo normals", self.app)\n        self.assertIn("cumulative balances between storms", self.app)\n'''
frontend_test = replace_if_present(frontend_test, old_frontend_test, new_frontend_test, "frontend readme tests")
FRONTEND_TEST.write_text(frontend_test, encoding="utf-8")

print("Applied transferred Zero G MX2001 + ETo loss reference to all modeled canyon balances and documentation")
